mapper.select:
select a.id, a.title, a.content, a.cover_img, a.state, a.category_id, c.category_name as categoryName, a.create_user, a.create_time, a.update_time from article a left join category c on a.category_id = c.id
a.category_id = #{categoryId}
and a.state = #{state}
and a.create_user = #{userId}
